anyFilterEvent(filter: any) {
  if (filter.key === 'IPType') {
    if (filter.model === 'all') this.onReset();
    else {
      this.currentIPCategory = filter.model;
      this.setSeriesData('accounted_active_application'); //ENTER COMPARISON VIEW
    }
  }
}
