  if (!this.selectedRecipientSystem()) {
    return [];
  }

  return this.selectedRecipientSystem().ipTypeCategoryBag.map(
    (category: any) => ({
      label: category.ipTypeLabel,
      value: category.ipTypeCategory,
    })
  );
});

